import * as T from'./vendor/three.module.min.js';
// Temporary additive poses restore before the walking mixer runs; no accumulation.
export class PartnerAttackPose{
 constructor(model,profile=null,forwardYaw=0){this.model=model;this.bones=[];if(Array.isArray(profile)){model.updateMatrixWorld(true);const lateral=new T.Vector3(Math.cos(forwardYaw),0,-Math.sin(forwardYaw)).applyQuaternion(model.getWorldQuaternion(new T.Quaternion()));for(const p of profile)this.bones.push({...p,base:p.bone.quaternion.clone(),axis:lateral.clone().applyQuaternion(p.bone.getWorldQuaternion(new T.Quaternion()).invert()).normalize()});}else model.traverse(b=>{if(b.isBone&&/Spine|Head_0|0_(Left|Right)_Limb_0|Chest|UpperArm|Head$/.test(b.name))this.bones.push({bone:b,base:b.quaternion.clone()});});this.offset=new T.Quaternion();this.axis=new T.Vector3(1,0,0);this.applied=false;}
 reset(){if(!this.applied)return;for(const b of this.bones)b.bone.quaternion.copy(b.base);this.model.rotation.x=0;this.model.rotation.z=0;this.applied=false;}
 apply(attack){if(!attack)return;const t=Math.min(1,attack.age/attack.duration),prepare=Math.sin(Math.PI*Math.min(1,t/.34)),strike=Math.sin(Math.PI*Math.max(0,Math.min(1,(t-.25)/.75))),jump=attack.kind==='jump';for(const b of this.bones){b.base.copy(b.bone.quaternion);const head=b.role?b.role==='head':b.bone.name.includes('Head'),limb=b.role?b.role==='limb':b.bone.name.includes('Limb'),sign=b.bone.name.includes('Left')?-1:1;const angle=limb?sign*(prepare*.10-strike*.19):head?prepare*.065-strike*.105:prepare*.05-strike*.09;this.offset.setFromAxisAngle(b.axis||this.axis,angle*(b.role?.55:.7)*(jump?1.1:1));b.bone.quaternion.multiply(this.offset);}this.model.rotation.x=prepare*.065-strike*.105;this.model.rotation.z=attack.kind==='turn'?Math.sin(t*Math.PI*2)*.14:0;this.applied=true;}
}
